using System;using System.IO;using System.Collections.Generic;using ScoreModern.RecoveredFragments;
class InputChordRhythmProof {
 static int Main(string[] a){try{byte[] ds=File.ReadAllBytes(a[0]),before=File.ReadAllBytes(a[1]),tokens=File.ReadAllBytes(a[2]),bounds=File.ReadAllBytes(a[3]),after=File.ReadAllBytes(a[4]);int count=BitConverter.ToInt16(ds,0x8798),events=BitConverter.ToInt16(ds,0x879c);float[] values=new float[events];Buffer.BlockCopy(tokens,2,values,0,events*4);var rows=new List<float[]>();for(int i=0;i<count;i++){var p=new float[15];Buffer.BlockCopy(before,i*60,p,0,60);rows.Add(p);}int[] stems=new int[BitConverter.ToInt16(ds,0x8788)];for(int i=0;i<stems.Length;i++)stems[i]=BitConverter.ToInt16(before,0x2a30+i*2);float staff=BitConverter.ToSingle(ds,0x8780);var result=InputChordRhythmRecords.Apply(rows,values,BitConverter.ToSingle(bounds,0),BitConverter.ToSingle(bounds,4),BitConverter.ToSingle(ds,0x8040+(int)staff*4)/25,stems,BitConverter.ToInt16(ds,0x8790)<0,BitConverter.ToSingle(ds,0x3a70));int checks=0;for(int i=0;i<count;i++)for(int p=0;p<15;p++){if(BitConverter.ToInt32(BitConverter.GetBytes(result[i][p]),0)!=BitConverter.ToInt32(after,i*60+p*4))throw new Exception("Record "+i+" P"+(p+1)+": "+result[i][p]+" != "+BitConverter.ToSingle(after,i*60+p*4));checks++;}Console.WriteLine("PASS "+checks+" original chord rhythm words");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
